def search(lst):
    count_dict = {}
    for num in lst:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    max_num = -1
    for num in count_dict:
        if num > 0 and count_dict[num] >= num:
            max_num = max(max_num, num)

    return max_num

