def smallest_change(arr):
    count = 0
    freq = {}

    # Count the frequency of each element in the array
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Count the number of elements that appear an odd number of times
    for count in freq.values():
        if count % 2 != 0:
            count += 1

    return count // 2

