def smallest_change(arr):
    count = 0
    freq = {}

    # Count the frequency of each element in the array
    for num in arr:
        if num in freq:
            freq[num] += 1
        else:
            freq[num] = 1

    # Calculate the number of elements that need to be changed
    for num in freq:
        count += max(0, 2 * freq[num] - len(arr))

    return count // 2

