def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        if x in row:
            indices = [j for j, val in enumerate(row) if val == x]
            result.append((i, max(indices)))
            result.append((i, min(indices)))
            indices.remove(max(indices))
            indices.remove(min(indices))
            for index in sorted(indices, reverse=True):
                result.append((i, index))
    return result

def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        if x in row:
            coordinates = [(j, len(row) - 1 - k) for k, j in enumerate(range(len(row))) if row[j] == x]
            result.extend([(i, j) for j in sorted(coordinates, key=lambda y: y[1], reverse=True)])
    return sorted(result, key=lambda y: y[0])

