def encode(message):
    vowels = 'aeiou'
    encoded_message = ''

    for char in message:
        if char.isalpha():
            if char.isupper():
                encoded_message += char.swapcase()
            else:
                encoded_message += char.swapcase()

            if char.lower() in vowels:
                index = vowels.index(char.lower()) + 2
                if index >= len(vowels):
                    index -= len(vowels)
                encoded_message = encoded_message.replace(char, vowels[index])
        else:
            encoded_message += char

    return encoded_message

