def match_parens(lst):
    s1, s2 = lst
    stack = []

    for c in s1 + s2:
        if c == '(':
            stack.append(c)
        elif c == ')':
            if stack:
                stack.pop()
            else:
                stack.append(c)

    return 'Yes' if not stack else 'No'

print(match_parens(['()(', ')']))  # 'Yes'
print(match_parens([')', ')']))  # 'No'

def match_parens(lst):
    s1, s2 = lst
    count = 0
    for c in s1 + s2:
        if c == '(':
            count += 1
        elif c == ')':
            count -= 1
        if count < 0:
            return 'No'
    return 'Yes' if count == 0 else 'No'

