def solve(s):
    result = ""
    reverse = False
    for char in s:
        if char.isalpha():
            if result and result[-1].isalpha():
                result = result[:-1]
            if char.islower():
                result += char.upper()
            else:
                result += char.lower()
        else:
            if reverse:
                result = char + result
            else:
                result += char
            reverse = not reverse
    if not any(c.isalpha() for c in s):
        result = result[::-1]
    return result

